\begin{theorem}[Cauchy–Schwarz]
For real numbers \(a_{1},\dots ,a_{n}\) and \(b_{1},\dots ,b_{n}\),
\[
\biggl(\sum_{i=1}^{n}a_{i}b_{i}\biggr)^{2}\le
\biggl(\sum_{i=1}^{n}a_{i}^{2}\biggr)\,
\biggl(\sum_{i=1}^{n}b_{i}^{2}\biggr),
\]
with equality exactly when the two families are proportional, i.e.\ there exists a real constant \(k\) such that \(a_{i}=k\,b_{i}\) for every \(i\) (or one of the vectors is the zero vector).
\end{theorem}

\begin{proof}
\textbf{1. Vector notation.}  
Let \(\mathbf a=(a_{1},\dots ,a_{n})\) and \(\mathbf b=(b_{1},\dots ,b_{n})\) be vectors in \(\mathbb R^{n}\).  
Define the inner product and Euclidean norm by
\[
\langle\mathbf a,\mathbf b\rangle =\sum_{i=1}^{n}a_{i}b_{i},
\qquad
\|\mathbf a\|^{2}= \sum_{i=1}^{n}a_{i}^{2},
\qquad
\|\mathbf b\|^{2}= \sum_{i=1}^{n}b_{i}^{2}.
\]
In this language the inequality to be proved is
\begin{equation}
\langle\mathbf a,\mathbf b\rangle^{2}\le \|\mathbf a\|^{2}\,\|\mathbf b\|^{2}.
\tag{1}
\end{equation}

\textbf{2. Degenerate cases.}  
If \(\mathbf a=\mathbf 0\) or \(\mathbf b=\mathbf 0\) then \(\langle\mathbf a,\mathbf b\rangle =0\) and both sides of \eqref{1} equal \(0\); thus \eqref{1} holds with equality.  
Henceforth assume \(\mathbf a\neq\mathbf 0\) and \(\mathbf b\neq\mathbf 0\).

\textbf{3. Construction of a non‑negative quadratic form.}  
For an arbitrary real scalar \(t\) consider
\begin{equation}
Q(t)=\sum_{i=1}^{n}\bigl(a_{i}-t\,b_{i}\bigr)^{2}.
\tag{2}
\end{equation}
Each term \((a_{i}-t b_{i})^{2}\) is a square; therefore \(Q(t)\ge 0\) for all \(t\in\mathbb R\).

Using the identity \((a_{i}-t b_{i})^{2}=a_{i}^{2}-2t\,a_{i}b_{i}+t^{2}b_{i}^{2}\) we expand \eqref{2}:
\begin{align*}
Q(t)
&=\sum_{i=1}^{n}a_{i}^{2}
   -2t\sum_{i=1}^{n}a_{i}b_{i}
   +t^{2}\sum_{i=1}^{n}b_{i}^{2}  \\
&=\|\mathbf a\|^{2}
   -2t\langle\mathbf a,\mathbf b\rangle
   +t^{2}\|\mathbf b\|^{2}.
\end{align*}
Hence
\begin{equation}
Q(t)=\|\mathbf b\|^{2}t^{2}
      -2\langle\mathbf a,\mathbf b\rangle t
      +\|\mathbf a\|^{2}.
\tag{3}
\end{equation}
Thus \(Q(t)\) is a quadratic polynomial in \(t\) with leading coefficient \(\|\mathbf b\|^{2}>0\).

\textbf{4. Discriminant condition.}  
A real quadratic \(p(t)=\alpha t^{2}+\beta t+\gamma\) that satisfies \(p(t)\ge 0\) for every real \(t\) must have non‑positive discriminant,
\(\beta^{2}-4\alpha\gamma\le 0\).
Applying this to \eqref{3} we obtain
\[
\Delta
=\bigl(-2\langle\mathbf a,\mathbf b\rangle\bigr)^{2}
   -4\|\mathbf b\|^{2}\|\mathbf a\|^{2}
=4\bigl(\langle\mathbf a,\mathbf b\rangle^{2}
        -\|\mathbf a\|^{2}\|\mathbf b\|^{2}\bigr).
\]
Since \(Q(t)\ge 0\) for all \(t\), \(\Delta\le 0\); dividing by the positive constant \(4\) yields exactly \eqref{1}.

\textbf{5. Equality condition.}  
Equality in \eqref{1} occurs iff \(\Delta=0\). Then the quadratic \eqref{3} has a unique real root \(t_{0}\) and \(Q(t_{0})=0\). Because
\[
Q(t_{0})=\sum_{i=1}^{n}\bigl(a_{i}-t_{0}b_{i}\bigr)^{2},
\]
the sum of non‑negative squares can be zero only when each square vanishes:
\(a_{i}=t_{0}b_{i}\) for all \(i\). Hence \(\mathbf a = t_{0}\mathbf b\); the vectors are linearly dependent.

Conversely, if \(\mathbf a = k\mathbf b\) for some \(k\in\mathbb R\) (including \(k=0\)), then each term in \eqref{2} vanishes for \(t=k\), giving \(Q(k)=0\) and thus \(\Delta=0\); consequently equality holds.

Therefore equality holds \emph{iff} there exists a scalar \(k\in\mathbb R\) such that \(\mathbf a = k\mathbf b\) (or equivalently the two sequences are proportional).

\textbf{6. Conclusion.}  
The Cauchy–Schwarz inequality follows from the universal non‑negativity of the sum of squares \(Q(t)\) and the discriminant condition for quadratics. The zero‑vector case is handled separately, and the equality case is fully characterized. \(\square\)
\end{proof}
